// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 seed) public {
        // Use seed to generate a block number that is not divisible by 15
        // bound to avoid overflow, then ensure block.number % 15 != 0
        uint256 blockNum = bound(seed, 1, type(uint256).max);
        vm.assume(blockNum % 15 != 0);
        vm.roll(blockNum);

        // Ensure contract has no ether to simplify
        vm.deal(address(c), 0);

        // Attempt to call fallback with exactly 10 ether
        vm.deal(address(this), 10 ether);
        (bool success, ) = address(c).call{value: 10 ether}("");

        // On reference C, the call succeeds (no revert). On mutated version, it reverts.
        assertTrue(success);
    }
}

